export type AgentSteeringCompletionStatus =
  | "pending"
  | "suspended"
  | "in_progress"
  | "delivered"
  | "discarded"
  | "failed";

export interface AgentSteeringCompletionResult {
  [key: string]: unknown;
}

export interface AgentSteeringCompletionInput {
  id?: string;
  requesterSessionKey: string;
  result?: string | AgentSteeringCompletionResult;
  prompt?: string;
  status?: Extract<AgentSteeringCompletionStatus, "pending" | "suspended">;
  createdAt?: number;
}

export interface AgentSteeringCompletion {
  id: string;
  requesterSessionKey: string;
  status: AgentSteeringCompletionStatus;
  result?: string | AgentSteeringCompletionResult;
  prompt?: string;
  mergedPrompt?: string;
  steeringLeaseId?: string;
  createdAt: number;
  updatedAt: number;
  leasedAt?: number;
  acknowledgedAt?: number;
  releasedAt?: number;
}

export interface AgentSteeringLeaseOptions {
  requesterSessionKey: string;
  leaseId?: string;
  now?: number;
  staleAfterMs?: number;
}

export interface AgentSteeringLease {
  id: string;
  completionId: string;
  requesterSessionKey: string;
  steeringLeaseId: string;
  leaseId: string;
  mergedPrompt: string;
  prompt: string;
  result?: string | AgentSteeringCompletionResult;
  completion: AgentSteeringCompletion;
}

export interface AgentSteeringAckOptions {
  id?: string;
  completionId?: string;
  requesterSessionKey?: string;
  steeringLeaseId?: string;
  leaseId?: string;
  now?: number;
}

export interface AgentSteeringReleaseOptions extends AgentSteeringAckOptions {}

export interface AgentSteeringListOptions {
  requesterSessionKey: string;
  includeSuspended?: boolean;
  now?: number;
  staleAfterMs?: number;
}

export interface AgentSteeringQueueOptions {
  now?: () => number;
  staleAfterMs?: number;
  idFactory?: () => string;
}

const DEFAULT_STALE_AFTER_MS = 5 * 60 * 1000;
const TERMINAL_STATUSES = new Set<AgentSteeringCompletionStatus>([
  "delivered",
  "discarded",
  "failed",
]);

function stringifyResult(result: string | AgentSteeringCompletionResult | undefined): string {
  if (result === undefined) return "";
  if (typeof result === "string") return result;
  try {
    return JSON.stringify(result);
  } catch {
    return String(result);
  }
}

function mergePrompt(
  prompt: string | undefined,
  result: string | AgentSteeringCompletionResult | undefined,
): string {
  const resultText = stringifyResult(result);
  const promptText = prompt?.trim() ?? "";
  if (!resultText) return promptText;
  if (!promptText) return resultText;
  return `${promptText}\n${resultText}`;
}

function defaultIdFactory(): string {
  const cryptoObject = (globalThis as { crypto?: { randomUUID?: () => string } }).crypto;
  if (cryptoObject?.randomUUID) return cryptoObject.randomUUID();
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
}

/**
 * In-process registry for completed steering work.  A lease is the ownership
 * boundary: a completion can only be acknowledged by the exact lease which
 * received it.  Terminal entries are immutable and can never be leased again.
 */
export class AgentSteeringQueue {
  private readonly completions = new Map<string, AgentSteeringCompletion>();
  private readonly now: () => number;
  private readonly staleAfterMs: number;
  private readonly idFactory: () => string;

  constructor(options: AgentSteeringQueueOptions = {}) {
    this.now = options.now ?? (() => Date.now());
    this.staleAfterMs = options.staleAfterMs ?? DEFAULT_STALE_AFTER_MS;
    this.idFactory = options.idFactory ?? defaultIdFactory;
  }

  enqueue(input: AgentSteeringCompletionInput): AgentSteeringCompletion {
    const timestamp = input.createdAt ?? this.now();
    const id = input.id ?? this.idFactory();
    const existing = this.completions.get(id);
    if (existing) {
      if (existing.requesterSessionKey !== input.requesterSessionKey) {
        throw new Error(`Steering completion already exists for a different requester: ${id}`);
      }
      return existing;
    }

    const completion: AgentSteeringCompletion = {
      id,
      requesterSessionKey: input.requesterSessionKey,
      status: input.status ?? "pending",
      result: input.result,
      prompt: input.prompt,
      mergedPrompt: mergePrompt(input.prompt, input.result),
      createdAt: timestamp,
      updatedAt: timestamp,
    };
    this.completions.set(id, completion);
    return { ...completion };
  }

  add(input: AgentSteeringCompletionInput): AgentSteeringCompletion {
    return this.enqueue(input);
  }

  listPending(options: AgentSteeringListOptions): AgentSteeringCompletion[] {
    const now = options.now ?? this.now();
    const staleAfterMs = options.staleAfterMs ?? this.staleAfterMs;
    return [...this.completions.values()]
      .filter((completion) => completion.requesterSessionKey === options.requesterSessionKey)
      .filter((completion) => {
        if (completion.status === "pending") return true;
        if (completion.status === "suspended") return options.includeSuspended === true;
        if (completion.status === "in_progress") {
          return now - (completion.leasedAt ?? completion.updatedAt) > staleAfterMs;
        }
        return false;
      })
      .filter((completion) => !TERMINAL_STATUSES.has(completion.status))
      .sort((left, right) => left.createdAt - right.createdAt)
      .map((completion) => ({ ...completion }));
  }

  pending(options: AgentSteeringListOptions): AgentSteeringCompletion[] {
    return this.listPending(options);
  }

  lease(options: AgentSteeringLeaseOptions): AgentSteeringLease | undefined {
    const now = options.now ?? this.now();
    const staleAfterMs = options.staleAfterMs ?? this.staleAfterMs;
    const candidates = [...this.completions.values()]
      .filter((completion) => completion.requesterSessionKey === options.requesterSessionKey)
      .filter((completion) => completion.status === "pending" || completion.status === "suspended")
      .sort((left, right) => left.createdAt - right.createdAt);

    for (const completion of candidates) {
      const steeringLeaseId = options.leaseId ?? this.idFactory();
      completion.status = "in_progress";
      completion.steeringLeaseId = steeringLeaseId;
      completion.leasedAt = now;
      completion.updatedAt = now;
      completion.mergedPrompt = mergePrompt(completion.prompt, completion.result);

      return {
        id: completion.id,
        completionId: completion.id,
        requesterSessionKey: completion.requesterSessionKey,
        steeringLeaseId,
        leaseId: steeringLeaseId,
        mergedPrompt: completion.mergedPrompt ?? "",
        prompt: completion.mergedPrompt ?? "",
        result: completion.result,
        completion: { ...completion },
      };
    }

    // A stale lease is recoverable.  Only the owner session may take it back.
    for (const completion of [...this.completions.values()]) {
      if (completion.requesterSessionKey !== options.requesterSessionKey) continue;
      if (completion.status !== "in_progress") continue;
      const leasedAt = completion.leasedAt ?? completion.updatedAt;
      if (now - leasedAt <= staleAfterMs) continue;

      const steeringLeaseId = options.leaseId ?? this.idFactory();
      completion.steeringLeaseId = steeringLeaseId;
      completion.leasedAt = now;
      completion.updatedAt = now;
      completion.mergedPrompt = mergePrompt(completion.prompt, completion.result);
      return {
        id: completion.id,
        completionId: completion.id,
        requesterSessionKey: completion.requesterSessionKey,
        steeringLeaseId,
        leaseId: steeringLeaseId,
        mergedPrompt: completion.mergedPrompt ?? "",
        prompt: completion.mergedPrompt ?? "",
        result: completion.result,
        completion: { ...completion },
      };
    }

    return undefined;
  }

  leaseCompletion(options: AgentSteeringLeaseOptions): AgentSteeringLease | undefined {
    return this.lease(options);
  }

  ack(options: AgentSteeringAckOptions): boolean {
    const completion = this.find(options);
    if (!completion) return false;
    if (completion.status !== "in_progress") return false;
    const leaseId = options.steeringLeaseId ?? options.leaseId;
    if (!leaseId || completion.steeringLeaseId !== leaseId) return false;
    if (
      options.requesterSessionKey !== undefined &&
      completion.requesterSessionKey !== options.requesterSessionKey
    ) {
      return false;
    }
    completion.status = "delivered";
    completion.acknowledgedAt = options.now ?? this.now();
    completion.updatedAt = completion.acknowledgedAt;
    return true;
  }

  acknowledge(options: AgentSteeringAckOptions): boolean {
    return this.ack(options);
  }

  release(options: AgentSteeringReleaseOptions): boolean {
    const completion = this.find(options);
    if (!completion) return false;
    if (completion.status !== "in_progress") return false;
    const leaseId = options.steeringLeaseId ?? options.leaseId;
    if (!leaseId || completion.steeringLeaseId !== leaseId) return false;
    if (
      options.requesterSessionKey !== undefined &&
      completion.requesterSessionKey !== options.requesterSessionKey
    ) {
      return false;
    }
    const timestamp = options.now ?? this.now();
    completion.status = "pending";
    completion.releasedAt = timestamp;
    completion.updatedAt = timestamp;
    delete completion.steeringLeaseId;
    delete completion.leasedAt;
    return true;
  }

  cancel(id: string, requesterSessionKey?: string): boolean {
    const completion = this.completions.get(id);
    if (!completion) return false;
    if (requesterSessionKey !== undefined && completion.requesterSessionKey !== requesterSessionKey) {
      return false;
    }
    if (TERMINAL_STATUSES.has(completion.status)) return false;
    completion.status = "discarded";
    completion.updatedAt = this.now();
    delete completion.steeringLeaseId;
    delete completion.leasedAt;
    return true;
  }

  terminate(id: string, requesterSessionKey?: string): boolean {
    return this.cancel(id, requesterSessionKey);
  }

  fail(id: string, requesterSessionKey?: string): boolean {
    const completion = this.completions.get(id);
    if (!completion) return false;
    if (requesterSessionKey !== undefined && completion.requesterSessionKey !== requesterSessionKey) {
      return false;
    }
    if (TERMINAL_STATUSES.has(completion.status)) return false;
    completion.status = "failed";
    completion.updatedAt = this.now();
    delete completion.steeringLeaseId;
    delete completion.leasedAt;
    return true;
  }

  get(id: string): AgentSteeringCompletion | undefined {
    const completion = this.completions.get(id);
    return completion ? { ...completion } : undefined;
  }

  private find(options: AgentSteeringAckOptions): AgentSteeringCompletion | undefined {
    const id = options.completionId ?? options.id;
    if (!id) return undefined;
    return this.completions.get(id);
  }
}

export const agentSteeringQueue = new AgentSteeringQueue();

export function createAgentSteeringQueue(options?: AgentSteeringQueueOptions): AgentSteeringQueue {
  return new AgentSteeringQueue(options);
}

export function enqueueAgentSteeringCompletion(
  input: AgentSteeringCompletionInput,
  queue: AgentSteeringQueue = agentSteeringQueue,
): AgentSteeringCompletion {
  return queue.enqueue(input);
}

export function leaseAgentSteeringCompletion(
  options: AgentSteeringLeaseOptions,
  queue: AgentSteeringQueue = agentSteeringQueue,
): AgentSteeringLease | undefined {
  return queue.lease(options);
}

export function acknowledgeAgentSteeringCompletion(
  options: AgentSteeringAckOptions,
  queue: AgentSteeringQueue = agentSteeringQueue,
): boolean {
  return queue.ack(options);
}

export function releaseAgentSteeringCompletion(
  options: AgentSteeringReleaseOptions,
  queue: AgentSteeringQueue = agentSteeringQueue,
): boolean {
  return queue.release(options);
}

export function listPendingAgentSteeringCompletions(
  options: AgentSteeringListOptions,
  queue: AgentSteeringQueue = agentSteeringQueue,
): AgentSteeringCompletion[] {
  return queue.listPending(options);
}

